function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 50) return 'nums needs 2 to 50 values.';
  const n = nums.length;
  const seen = new Set();
  for (const v of nums) {
    if (!Number.isInteger(v) || v < 1 || v > n) return 'Each value must be a whole number from 1 to nums.length.';
    if (seen.has(v)) return 'nums must be a permutation: no value may repeat.';
    seen.add(v);
  }
  return null;
}

