function semiOrderedPermutation(nums) {
  const n = nums.length;
  const first = nums.indexOf(1);
  const last = nums.indexOf(n);

  let moves = first + (n - 1 - last);
  if (first > last) {
    moves--;
  }
  return moves;
}

