function semiOrderedPermutation(nums) {
  const n = nums.length;
  const done = (arr) => arr[0] === 1 && arr[n - 1] === n;
  if (n <= 8) {
    // Breadth-first search over every arrangement reachable by neighbour swaps.
    const start = nums.join(',');
    const dist = new Map([[start, 0]]);
    const queue = [nums.slice()];
    for (let head = 0; head < queue.length; head++) {
      const arr = queue[head];
      const d = dist.get(arr.join(','));
      if (done(arr)) return d;
      for (let i = 0; i + 1 < n; i++) {
        const next = arr.slice();
        [next[i], next[i + 1]] = [next[i + 1], next[i]];
        const key = next.join(',');
        if (!dist.has(key)) {
          dist.set(key, d + 1);
          queue.push(next);
        }
      }
    }
    return -1;
  }
  // Too many arrangements to search: bubble 1 to the front, then n to the back, counting swaps.
  const arr = nums.slice();
  let swaps = 0;
  for (let i = arr.indexOf(1); i > 0; i--, swaps++) [arr[i - 1], arr[i]] = [arr[i], arr[i - 1]];
  for (let i = arr.indexOf(n); i < n - 1; i++, swaps++) [arr[i], arr[i + 1]] = [arr[i + 1], arr[i]];
  return swaps;
}

