function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'small' ? pick(2, 7) : pick(40, 50);
  const nums = Array.from({ length: n }, (_, i) => i + 1);
  for (let i = n - 1; i > 0; i--) {
    const j = pick(0, i);
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }
  const mode = pick(0, 3);
  const place = (value, index) => {
    const at = nums.indexOf(value);
    [nums[at], nums[index]] = [nums[index], nums[at]];
  };
  if (mode === 1) {
    // 1 to the right of n, so their paths cross.
    const a = pick(0, n - 2);
    const b = pick(a + 1, n - 1);
    place(n, a);
    place(1, b);
  } else if (mode === 2) {
    // Already semi-ordered, or only one of the two ends needs work.
    place(1, 0);
    if (rand() < 0.5) place(n, n - 1);
  }
  return [nums];
}
